      <main data-testid="canvas-workspace" className={`canvas-workspace ${preview?'preview-mode':''}`} onClick={e=>{if(e.target===e.currentTarget)dispatch({type:'SELECT_NODE',payload:[]})}} onWheel={e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();const workspace=e.currentTarget.getBoundingClientRect(),next=zoomAtPoint({zoom:state.zoom,panX:viewport.x,panY:viewport.y},state.zoom+(e.deltaY>0?-.1:.1),{x:e.clientX-workspace.left,y:e.clientY-workspace.top});dispatch({type:'SET_ZOOM',payload:next.zoom});setViewport({x:next.panX,y:next.panY})}}} onPointerDown={e=>{if(e.button===1||(e.button===0&&(window as any).__zyloraSpacePressed)){e.preventDefault();const el=e.currentTarget as HTMLElement;pan.current={x:e.clientX,y:e.clientY,left:viewport.x,top:viewport.y};el.setPointerCapture(e.pointerId)}}} onPointerMove={e=>{if(pan.current){e.preventDefault();setViewport({x:pan.current.left+e.clientX-pan.current.x,y:pan.current.top+e.clientY-pan.current.y})}}} onPointerUp={e=>{if(pan.current)(e.currentTarget as HTMLElement).releasePointerCapture?.(e.pointerId);pan.current=null}} onPointerCancel={()=>{pan.current=null}} onContextMenu={e=>{if(state.selectedNodeIds.length){e.preventDefault();setContext({x:e.clientX,y:e.clientY})}}} onDragEnter={e=>{if(Array.from(e.dataTransfer.types).some(t=>t==='Files'||t==='application/x-zylora-node')){e.preventDefault();setFileDrop(true)}}} onDragOver={e=>{if(Array.from(e.dataTransfer.types).some(t=>t==='Files'||t==='application/x-zylora-node'))e.preventDefault()}} onDragLeave={e=>{if(e.currentTarget===e.target)setFileDrop(false)}} onDrop={onWorkspaceDrop}>
        {!!state.selectedNodeIds.length&&<div className="canvas-toolbar-dock"><ContextToolbar onFit={fit} onPreview={()=>setPreview(!preview)}/><span className="device-toolbar">{(['desktop','tablet','mobile'] as const).map(bp=><button key={bp} className={state.currentBreakpoint===bp?'active':''} title={bp} aria-label={`${bp} preview`} onClick={()=>dispatch({type:'SET_BREAKPOINT',payload:bp})}>{bp==='desktop'?'▰':'▯'}</button>)}</span></div>}{fileDrop&&<div className="canvas-file-drop" aria-live="polite">Drop to add to your page</div>}<div className="artboard-wrap" style={{width:width*state.zoom}}><div data-testid="studio-artboard" data-viewport={`${viewport.x},${viewport.y},${state.zoom}`} className="studio-canvas" style={{width,height:'auto',minHeight:766,transform:`translate3d(${viewport.x}px,${viewport.y}px,0) scale(${state.zoom})`}}>{page?<CanvasNode nodeId={page.rootNodeId}/>:<div className="canvas-loading"><span/><p>Preparing your canvas…</p></div>}{state.snapLines.map((line,i)=><div key={i} className={`snap-guide ${line.orientation} snap-${line.type}`} style={line.orientation==='vertical'?{left:line.position}:{top:line.position}}>{line.label&&<span>{line.label}</span>}</div>)}<SelectionOverlay/></div></div><PageNavigator onFit={fit}/></main>
